class Solution:
    def largestPalindrome(self, n: int) -> int:
        if n == 0:
            return 0
        if n == 1:
            return 9

        max_num = 10**n - 1
        min_num = 10**(n-1)

        for a in range(max_num, min_num, -1):
            palindrome = int(str(a) + str(a)[::-1])
            for b in range(max_num, int(palindrome**0.5), -1):
                if palindrome % b == 0 and min_num <= palindrome // b <= max_num:
                    return palindrome % 1337
