class Solution:
    def largestPalindrome(self, n: int) -> int:
        if n == 0:
            return 0
        max_num = 10**n - 1
        for a in range(max_num, max_num // 10 - 1, -1):
            palindrome = a * (10**(n)) + self.make_palindrome(a // 10)
            for b in range(max_num, max((max_num * max_num) ** 0.5, palindrome // max_num), -1):
                if palindrome % b == 0:
                    return palindrome % 1337
        return -1

    def make_palindrome(self, half: int) -> int:
        return int(str(half) + str(half)[::-1])
