class Solution:
    def largestPalindrome(self, n: int) -> int:
        if n == 0:
            return 0

        max_num = 10**n - 1
        for a in range(max_num, 10**(n-1)-1, -1):
            palindrome = a * (10**(2*n)) + self.reverse_number(a)
            for b in range(max_num, a-1, -1):
                if palindrome % b == 0 and palindrome // b <= max_num:
                    return palindrome % 1337
        return -1

    def reverse_number(self, x):
        rev = 0
        while x != 0:
            rev = rev * 10 + x % 10
            x //= 10
        return rev
```

