class Solution:
    def largestPalindrome(self, n: int) -> int:
        if n == 0:
            return 0

        def is_palindrome(num: int) -> bool:
            return str(num) == str(num)[::-1]

        upper_limit = 10**n - 1
        lower_limit = 10**(n-1)

        for x in range(upper_limit, lower_limit, -1):
            palindrome = x * x
            while palindrome > lower_limit * 10:
                if palindrome % 10 == 0:
                    continue
                y = palindrome // (10**(n-1))
                if y < lower_limit:
                    break
                if palindrome % 1337 == 0 and is_palindrome(palindrome):
                    return palindrome % 1337
                palindrome //= 10

        return -1
