def encode(string):
    ascii_values = [format(ord(char), '08b') for char in string]
    binary_string = ''.join(ascii_values)
    encoded_string = ''
    for bit in binary_string:
        if bit == '0':
            encoded_string += '000'
        else:
            encoded_string += '111'
    return encoded_string
