        'a': '\xe4', 'e': '\xeb', 'i': '\xef', 'o': '\xf6', 'u': '\xfc', 'y': '\xff'
    }

    for char, replacement in replacements.items():
        boring_text = boring_text.replace(char, replacement)

    return boring_text
